  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Doxazosin, the closest analogue sharing the 2,4-diamino-6,7-dimethoxyquinazoline piperazine amide core, has absolute oral bioavailability of 60–70% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Bunazosin, another close quinazoline-piperazine analogue, has absolute oral bioavailability of 44.1% in volunteers, well above the 20% threshold and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Trimazosin, a closely related quinazoline-piperazine antihypertensive, shows oral bioavailability of 61 ± 28% in normotensive volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Alfuzosin, a quinazoline alpha-blocker with the same 6,7-dimethoxyquinazoline-2,4-diamine pharmacophore, has mean oral bioavailability of 64% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Carbazeran has absolute oral bioavailability <5% in humans, but it is structurally distant and its low F is attributed to a different metabolic liability, so it does not outweigh the consistent high-F data from close analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is prazosin, a 2,4-diamino-6,7-dimethoxyquinazoline bearing a 4-(2-furoyl)piperazine. The closest structural analogues—doxazosin, bunazosin, trimazosin, and alfuzosin—all show human absolute oral bioavailability well above 20% (44–76%). The only low-F analogue, carbazeran, is structurally distant and has a distinct metabolic clearance mechanism. Therefore, the evidence strongly supports high oral bioavailability (F >= 20%).",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for prazosin itself is present in the provided evidence set.",
    "Formulation-specific or food-effect data for the query are not directly available, though close analogues show consistent high bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

